using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class RustonandHornsby_SheafIronworks : LayoutBase
{
    public RustonandHornsby_SheafIronworks()
    {
        Name = LayoutNamesEnums.RustonandHornsby_SheafIronworks;
        Owner = "Michael and Andrew Sharpe";
        Description = "Ruston and Hornsby were general engineers, locomotive and boiler engine builders and manufacturers, and this layout models the works complex in Lincoln. By the Second World War the Lincoln Boultham Works were producing narrow gauge and standard gauge railway locomotives, while the Sheaf Ironworks on the waterside produced a range of stationary engines, small and large marine engines, and engines for landing craft, patrol boats, minesweepers and submarines. Ruston and Hornsby were also equipped for the production of all the Matilda, Cavalier and Crusader tanks. The layout depicts part of the Sheaf Ironworks during the early 1940s, where the main line railway from Lincoln brought supplies in and out, and is modelled in 'OO' gauge. A pair of 7 1/4in gauge locomotives are displayed alongside it - a battery powered Ruston 48DS modelling locomotive 207103, built in 1941 and based at Rocks by Rail near Cottesmore, and a 20DL narrow gauge locomotive built to 2/3 scale and powered by a Ruston and Hornsby 5HP 1WB diesel engine.";
    }
}